head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > onheadertextimageclick]<br/>inputType='textImage', viewType='icon' 인 Header Cell 에서 이미지 영역을 마우스 왼쪽 버튼으로 클릭할 때 발생합니다.",
    "validation" : [
        "inputType='textImage', viewType='icon' 인 Header Cell 에서 이미지 영역을 마우스 왼쪽 버튼으로 클릭할 때 onheadertextimageclick 이벤트가 발생해야 합니다.",
        "headerId 파라미터로 클릭된 이미지가 속한 Header Cell 의 ID 값이 전달되어야 합니다.",
        "headerValue 파라미터로 클릭된 이미지가 속한 Header Cell 에 표시되는 값이 전달되어야 합니다.",
        "Header Cell 이 비활성화(disabled) 상태이면 이벤트가 발생하지 않아야 합니다.",
        "onheadertextimageclick 이벤트가 발생하면 onheaderclick 이벤트는 발생하지 않아야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성 (textImage Header 포함 그리드를 직접 구성)
    let grp_comp = $c.gcm.getTestGroup();

    let strTarget = '';
    strTarget += '<w2:gridView ' + $c.gcm.getNameSpace() + ' dataList="data:dlt_bind" rowNumVisible="false" rowStatusVisible="false" ev:onheaderclick="scwin.target1_onheaderclick" ev:onheadertextimageclick="scwin.target1_onheadertextimageclick" checkAllType="false" id="" style="width:560px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_grid_del.svg" id="column1" value="textImage"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        'target1',
        "gridView",
        strTarget,
        grp_comp
    );
};



// column1(textImage) Header 를 ID 로 비활성화 (인덱스 호출 결함 회피)
//  - 비활성화 후 이미지 영역 클릭 시 onheadertextimageclick 이벤트가 발생하지 않음을 확인
scwin.btn_setHeaderDisabled_onclick = function (e) {
    target1.setHeaderDisabled("column1", true);
    wf_body_bottom.getObj("scwin").setReturnValue("column1 Header 비활성화 설정 완료 (이미지 클릭 시 이벤트 미발생 확인)");
};



// 헤더 텍스트 영역 클릭 시 발생 (이미지 영역 클릭 시에는 미발생 → @spec2 관찰용)
scwin.target1_onheaderclick = function (headerId) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onheaderclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("headerId : " + headerId);
};



// textImage Header 이미지 영역 클릭 시 발생
//  - headerId / headerValue 는 e 객체가 아니라 String 인자 2개 → 각각 출력
scwin.target1_onheadertextimageclick = function (headerId, headerValue) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onheadertextimageclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("headerId : " + headerId);
    wf_body_bottom.getObj("scwin").setReturnValue("headerValue : " + headerValue);
};
